package main

import (
	"net/http/httptest"
	"testing"
)

func TestGetBookNotFound(t *testing.T) {
	rec := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/books/99", nil)
	req.SetPathValue("id", "99")
	getBook(rec, req)
	if rec.Code != 404 {
		t.Fatalf("status = %d, want 404", rec.Code)
	}
}
